import re


def parse_duration(text: str) -> int:
    """...docstring unchanged..."""
    if not isinstance(text, str):
        raise ValueError(f"invalid duration: {text!r}")
    # [0-9] rather than \d: \d would also accept non-ASCII digits.
    # fullmatch rather than match + "$": "$" would allow a trailing newline.
    match = _DURATION_RE.fullmatch(text)
    # Every part is optional in the pattern, so the empty string matches it;
    # at least one part is required.
    if not text or match is None:
        raise ValueError(f"invalid duration: {text!r}")
    return sum(
        int(number) * seconds
        for number, seconds in zip(match.groups(), _UNIT_SECONDS)
        if number is not None
    )


_UNIT_SECONDS = (86400, 3600, 60, 1)
_DURATION_RE = re.compile(
    r"(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?"
)
```

